#!/bin/bash
# Keeps Hyprland's window glow on the active theme's accent. Hyprland otherwise
# uses its default cyan, because no theme file sets this.
colors="$HOME/.local/state/omarchy/current/theme/colors.toml"
target="$HOME/.config/hypr/glow.lua"
accent=$(sed -nE 's/^accent *= *"#([0-9A-Fa-f]{6})".*/\1/p' "$colors" | head -1)
[[ -n $accent ]] || exit 0
cat > "$target.tmp" <<LUA
-- Generated by the hypr-glow theme hook. Follows the theme's accent.
hl.config({
  decoration = {
    glow = {
      color = "rgba(${accent,,}ee)",
    },
  },
})
LUA
mv "$target.tmp" "$target"
hyprctl reload >/dev/null 2>&1
